 "type": "string",
 "minLength": 1,
 "maxLength": 70,
 "description": "The challenge type, set by the LFI."
 },
 "status": {
 "allOf": [
 {
 "$ref": "#/components/schemas/OzoneConnectUserChallengeStatusCodes"
 }
 ],
 "description": "The status of the challenge. Supported values are as follows:\n\n* Pending: The challenge has not been sent or returned.\n\n* Sent: The challenge has been sent or returned.\n\n* Passed: The challenge has been verified.\n\n* TransmissionFailed: The challenge failed to be sent due a business or technical failure.\n\n* VerificationFailed: Verification of the challenge failed.\n"
 },
 "lastStatusUpdateDateTime": {
 "type": "string",
 "format": "date-time",
 "description": "The last status update to the challenge by the LFI."
 },
 "message": {
 "type": "string",
 "description": "Optional diagnostic message indicating failure reason."
 }
 },
 "required": [
 "challengeId",
 "challengeType",
 "status",
 "lastStatusUpdateDateTime"
 ],
 "description": "Properties of the user challenge."
 }
 },
 "required": [
 "data"
 ]
 }
 }
 }
